#!/usr/bin/env bash
# The cluster CA of usage-kafka on the local kind cluster (feature
# kafka-client-auth). Strimzi signs the broker certificates with it; the Kafka
# clients trust it. The CA is ours, not generated by Strimzi
# (generateCertificateAuthority: false), so it exists before the cluster does.
#
# The private key never goes to Git: it is generated here, kept in
# prototype/.kafka-ca/ (git-ignored) and loaded into the cluster as Secrets.
# EKS is to get its CA from External Secrets (not done yet).
#
#   ./prototype/kafka-ca.sh           create the CA if needed and load the Secrets
#   ./prototype/kafka-ca.sh --finish  drop the old CA once a replacement has rolled
#
# On a cluster whose Kafka still runs on a CA that Strimzi generated, the
# first run replaces it without downtime: the old certificate stays trusted
# and both generations are raised, so Strimzi rolls the brokers onto the new
# CA. When the Kafka cluster is Ready again, run it with --finish.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CA_DIR="${KAFKA_CA_DIR:-${SCRIPT_DIR}/.kafka-ca}"
CLUSTER="usage-kafka"
CERT_SECRET="${CLUSTER}-cluster-ca-cert"
KEY_SECRET="${CLUSTER}-cluster-ca"
# Namespaces whose Kafka clients trust the CA, each gets Secret usage-kafka-ca.
CLIENT_NAMESPACES=(usage gateway tenants)

finish=false
[[ "${1:-}" == "--finish" ]] && finish=true

ensure_ca() {
  if [[ -f "${CA_DIR}/ca.key" && -f "${CA_DIR}/ca.crt" ]]; then
    return
  fi
  echo "Creating the usage-kafka cluster CA in ${CA_DIR}..."
  mkdir -p "${CA_DIR}"
  chmod 700 "${CA_DIR}"
  openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:4096 -out "${CA_DIR}/ca.key"
  chmod 600 "${CA_DIR}/ca.key"
  openssl req -x509 -new -key "${CA_DIR}/ca.key" -days 3650 \
    -subj "/O=hamsp/CN=usage-kafka cluster CA (kind)" \
    -addext "basicConstraints=critical,CA:TRUE" \
    -addext "keyUsage=critical,keyCertSign,cRLSign" \
    -out "${CA_DIR}/ca.crt"
}

# put_secret NAMESPACE NAME ANNOTATION... -- FILE-ARGS...: creates or replaces
# a Secret with Strimzi's labels.
put_secret() {
  local ns=$1 name=$2
  shift 2
  local annotations=()
  while [[ "$1" != "--" ]]; do annotations+=("$1"); shift; done
  shift
  kubectl -n "${ns}" create secret generic "${name}" "$@" --dry-run=client -o yaml \
    | kubectl label --local -f - -o yaml strimzi.io/kind=Kafka "strimzi.io/cluster=${CLUSTER}" \
    | kubectl annotate --local -f - -o yaml "${annotations[@]}" \
    | if kubectl -n "${ns}" get secret "${name}" &>/dev/null; then kubectl replace -f -; else kubectl create -f -; fi
}

generation() { # SECRET ANNOTATION
  local v
  v=$(kubectl -n kafka get secret "$1" -o jsonpath="{.metadata.annotations.strimzi\.io/$2}" 2>/dev/null || true)
  echo "${v:-0}"
}

ensure_ca
for ns in kafka "${CLIENT_NAMESPACES[@]}"; do
  kubectl get namespace "${ns}" &>/dev/null || kubectl create namespace "${ns}" >/dev/null
done

current=$(kubectl -n kafka get secret "${CERT_SECRET}" -o jsonpath='{.data.ca\.crt}' 2>/dev/null | base64 -d || true)
cert_gen=$(generation "${CERT_SECRET}" ca-cert-generation)
key_gen=$(generation "${KEY_SECRET}" ca-key-generation)

if [[ -z "${current}" ]]; then
  echo "Loading the cluster CA into namespace kafka (new cluster)..."
  put_secret kafka "${CERT_SECRET}" "strimzi.io/ca-cert-generation=0" -- --from-file=ca.crt="${CA_DIR}/ca.crt"
  put_secret kafka "${KEY_SECRET}" "strimzi.io/ca-key-generation=0" -- --from-file=ca.key="${CA_DIR}/ca.key"
elif [[ "${current}" != "$(cat "${CA_DIR}/ca.crt")" ]]; then
  echo "Replacing the cluster CA of the running Kafka cluster (generation ${cert_gen} -> $((cert_gen + 1)))..."
  old_end=$(printf '%s\n' "${current}" | openssl x509 -noout -enddate | cut -d= -f2)
  old_name="ca-$(date -u -j -f '%b %e %T %Y %Z' "${old_end}" +%Y-%m-%dT%H-%M-%SZ 2>/dev/null \
    || date -u -d "${old_end}" +%Y-%m-%dT%H-%M-%SZ).crt"
  printf '%s\n' "${current}" > "${CA_DIR}/${old_name}"
  put_secret kafka "${CERT_SECRET}" "strimzi.io/ca-cert-generation=$((cert_gen + 1))" -- \
    --from-file=ca.crt="${CA_DIR}/ca.crt" --from-file="${old_name}=${CA_DIR}/${old_name}"
  put_secret kafka "${KEY_SECRET}" "strimzi.io/ca-key-generation=$((key_gen + 1))" -- \
    --from-file=ca.key="${CA_DIR}/ca.key"
  echo "Strimzi now rolls the brokers. When the Kafka cluster is Ready, run: $0 --finish"
elif ${finish}; then
  echo "Dropping the old CA certificates..."
  put_secret kafka "${CERT_SECRET}" "strimzi.io/ca-cert-generation=$((cert_gen + 1))" -- \
    --from-file=ca.crt="${CA_DIR}/ca.crt"
else
  echo "The cluster CA in namespace kafka is up to date."
fi

for ns in "${CLIENT_NAMESPACES[@]}"; do
  kubectl -n "${ns}" create secret generic usage-kafka-ca --from-file=ca.crt="${CA_DIR}/ca.crt" \
    --dry-run=client -o yaml | kubectl apply -f - >/dev/null
done
echo "The clients of ${CLIENT_NAMESPACES[*]} trust the CA (Secret usage-kafka-ca)."
